cat > /workspace/src/main.rs <<'RUST_EOF'
use std::env;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::path::Path;
use std::process::ExitCode;

const VERSION: &str = "0.7.0";
const DEFAULT_COLS: usize = 10;
const DEFAULT_PLACES: usize = 4;

#[derive(Clone, Copy, PartialEq)]
enum Format {
    Octal,
    LowerHex,
    UpperHex,
    Binary,
}

impl Format {
    fn prefix(&self) -> &'static str {
        match self {
            Format::Octal => "0o",
            Format::LowerHex => "0x",
            Format::UpperHex => "0x",
            Format::Binary => "0b",
        }
    }
    fn format_byte(&self, b: u8) -> String {
        match self {
            Format::Octal => format!("{:04o}", b),
            Format::LowerHex => format!("{:02x}", b),
            Format::UpperHex => format!("{:02X}", b),
            Format::Binary => format!("{:08b}", b),
        }
    }
}

#[derive(Clone, Copy)]
enum ArrayFormat {
    Rust,
    C,
    Golang,
    Python,
    Kotlin,
    Java,
    Swift,
    Fsharp,
}

#[derive(Default)]
struct Args {
    input_file: Option<String>,
    cols: Option<usize>,
    len: Option<usize>,
    format: Option<Format>,
    color: Option<bool>,
    array: Option<ArrayFormat>,
    func: Option<usize>,
    places: Option<usize>,
    prefix: Option<bool>,
}

fn usage_line(prog: &str) -> String {
    format!("Usage: {} [OPTIONS] [INPUTFILE]", prog)
}

fn print_help(prog: &str) {
    let help = format!(
        "Futuristic take on hexdump, made in Rust.\n\
         \n\
         \n\
         {usage}\n\
         \n\
         Arguments:\n  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\
         \n\
         Options:\n\
         \x20\x20-c, --cols <columns>        Set column length\n\
         \x20\x20-l, --len <len>             Set <len> bytes to read\n\
         \x20\x20-f, --format <format>       Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b) [possible values: o, x, X, b]\n\
         \x20\x20-t, --color <color>         Set color tint terminal output. 0 to disable, 1 to enable [possible values: 0, 1]\n\
         \x20\x20-a, --array <array_format>  Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f) [possible values: r, c, g, p, k, j, s, f]\n\
         \x20\x20-u, --func <func_length>    Set function wave length\n\
         \x20\x20-p, --places <func_places>  Set function wave output decimal places\n\
         \x20\x20-r, --prefix <prefix>       Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable [possible values: 0, 1]\n\
         \x20\x20-h, --help                  Print help\n\
         \x20\x20-V, --version               Print version\n",
        usage = usage_line(prog)
    );
    print!("{}", help);
}

fn print_version() {
    println!("hx {}", VERSION);
}

fn print_err(msg: &str, prog: &str, usage: bool) {
    eprintln!("error: {}", msg);
    eprintln!();
    if usage {
        eprintln!("{}", usage_line(prog));
        eprintln!();
    }
    eprintln!("For more information, try '--help'.");
}

fn parse_format(s: &str) -> Option<Format> {
    match s {
        "o" => Some(Format::Octal),
        "x" => Some(Format::LowerHex),
        "X" => Some(Format::UpperHex),
        "b" => Some(Format::Binary),
        _ => None,
    }
}

fn parse_array(s: &str) -> Option<ArrayFormat> {
    match s {
        "r" => Some(ArrayFormat::Rust),
        "c" => Some(ArrayFormat::C),
        "g" => Some(ArrayFormat::Golang),
        "p" => Some(ArrayFormat::Python),
        "k" => Some(ArrayFormat::Kotlin),
        "j" => Some(ArrayFormat::Java),
        "s" => Some(ArrayFormat::Swift),
        "f" => Some(ArrayFormat::Fsharp),
        _ => None,
    }
}

fn parse_bool(s: &str) -> Option<bool> {
    match s {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

fn program_name() -> String {
    env::args()
        .next()
        .and_then(|s| {
            Path::new(&s)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "hx".to_string())
}

struct ParseError {
    msg: String,
    show_usage: bool,
}

fn err_with_usage(msg: impl Into<String>) -> ParseError {
    ParseError {
        msg: msg.into(),
        show_usage: true,
    }
}

fn err_no_usage(msg: impl Into<String>) -> ParseError {
    ParseError {
        msg: msg.into(),
        show_usage: false,
    }
}

fn parse_args(argv: &[String]) -> Result<Result<Args, SpecialAction>, ParseError> {
    let mut args = Args::default();
    let mut i = 1;
    let mut positional_seen = false;
    let mut after_dd = false;

    // Track which options have been seen (for duplicate detection)
    let mut seen = std::collections::HashSet::new();

    while i < argv.len() {
        let arg = argv[i].clone();

        if after_dd {
            if positional_seen {
                return Err(err_with_usage(format!(
                    "unexpected argument '{}' found",
                    arg
                )));
            }
            args.input_file = Some(arg);
            positional_seen = true;
            i += 1;
            continue;
        }

        if arg == "--" {
            after_dd = true;
            i += 1;
            continue;
        }

        if arg == "-h" || arg == "--help" {
            return Ok(Err(SpecialAction::Help));
        }
        if arg == "-V" || arg == "--version" {
            return Ok(Err(SpecialAction::Version));
        }

        // --help= or --help=VALUE (also others)
        if let Some(rest) = arg.strip_prefix("--help=") {
            return Err(ParseError {
                msg: format!(
                    "unexpected value '{}' for '--help' found; no more were expected",
                    rest
                ),
                show_usage: true,
            });
        }

        // Try to parse long option with or without =
        if let Some(stripped) = arg.strip_prefix("--") {
            let (name, value) = if let Some(eq) = stripped.find('=') {
                (&stripped[..eq], Some(&stripped[eq + 1..]))
            } else {
                (stripped, None)
            };
            let val_owned: Option<String> = value.map(|s| s.to_string());
            let take_value = |i: &mut usize,
                              provided: Option<String>,
                              long_name: &str,
                              meta: &str|
             -> Result<String, ParseError> {
                if let Some(v) = provided {
                    Ok(v)
                } else {
                    *i += 1;
                    if *i < argv.len() {
                        Ok(argv[*i].clone())
                    } else {
                        Err(err_no_usage(format!(
                            "a value is required for '--{} <{}>' but none was supplied",
                            long_name, meta
                        )))
                    }
                }
            };
            match name {
                "cols" => {
                    if !seen.insert("cols") {
                        return Err(err_with_usage(
                            "the argument '--cols <columns>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "cols", "columns")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.cols = Some(n);
                }
                "len" => {
                    if !seen.insert("len") {
                        return Err(err_with_usage(
                            "the argument '--len <len>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "len", "len")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.len = Some(n);
                }
                "format" => {
                    if !seen.insert("format") {
                        return Err(err_with_usage(
                            "the argument '--format <format>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "format", "format")?;
                    let f = parse_format(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--format <format>'\n  [possible values: o, x, X, b]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.format = Some(f);
                }
                "color" => {
                    if !seen.insert("color") {
                        return Err(err_with_usage(
                            "the argument '--color <color>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "color", "color")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--color <color>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.color = Some(b);
                }
                "array" => {
                    if !seen.insert("array") {
                        return Err(err_with_usage(
                            "the argument '--array <array_format>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "array", "array_format")?;
                    let a = parse_array(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--array <array_format>'\n  [possible values: r, c, g, p, k, j, s, f]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.array = Some(a);
                }
                "func" => {
                    if !seen.insert("func") {
                        return Err(err_with_usage(
                            "the argument '--func <func_length>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "func", "func_length")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.func = Some(n);
                }
                "places" => {
                    if !seen.insert("places") {
                        return Err(err_with_usage(
                            "the argument '--places <func_places>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "places", "func_places")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.places = Some(n);
                }
                "prefix" => {
                    if !seen.insert("prefix") {
                        return Err(err_with_usage(
                            "the argument '--prefix <prefix>' cannot be used multiple times",
                        ));
                    }
                    let v = take_value(&mut i, val_owned, "prefix", "prefix")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--prefix <prefix>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.prefix = Some(b);
                }
                _ => {
                    return Err(err_with_usage(format!(
                        "unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'",
                        arg, arg, arg
                    )));
                }
            }
            i += 1;
            continue;
        }

        // Short option
        if arg.starts_with('-') && arg.len() >= 2 && arg != "-" {
            let bytes = arg.as_bytes();
            // Each short option is a single char; value can be appended or in next arg
            let c = bytes[1] as char;
            let inline = if bytes.len() > 2 {
                Some(String::from_utf8_lossy(&bytes[2..]).into_owned())
            } else {
                None
            };
            let take_val = |i: &mut usize,
                            provided: Option<String>,
                            long_name: &str,
                            meta: &str|
             -> Result<String, ParseError> {
                if let Some(v) = provided {
                    Ok(v)
                } else {
                    *i += 1;
                    if *i < argv.len() {
                        Ok(argv[*i].clone())
                    } else {
                        Err(err_no_usage(format!(
                            "a value is required for '--{} <{}>' but none was supplied",
                            long_name, meta
                        )))
                    }
                }
            };
            match c {
                'c' => {
                    if !seen.insert("cols") {
                        return Err(err_with_usage(
                            "the argument '--cols <columns>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "cols", "columns")?;
                    let n = v.parse::<usize>().map_err(|e| ParseError {
                        msg: format!(
                            "-c, --cols <integer> expected. ParseIntError {{ kind: {:?} }}\nerror: invalid digit found in string",
                            parse_int_kind(&e)
                        ),
                        show_usage: false,
                    })?;
                    let _ = n;
                    args.cols = Some(n);
                }
                'l' => {
                    if !seen.insert("len") {
                        return Err(err_with_usage(
                            "the argument '--len <len>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "len", "len")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.len = Some(n);
                }
                'f' => {
                    if !seen.insert("format") {
                        return Err(err_with_usage(
                            "the argument '--format <format>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "format", "format")?;
                    let f = parse_format(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--format <format>'\n  [possible values: o, x, X, b]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.format = Some(f);
                }
                't' => {
                    if !seen.insert("color") {
                        return Err(err_with_usage(
                            "the argument '--color <color>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "color", "color")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--color <color>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.color = Some(b);
                }
                'a' => {
                    if !seen.insert("array") {
                        return Err(err_with_usage(
                            "the argument '--array <array_format>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "array", "array_format")?;
                    let a = parse_array(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--array <array_format>'\n  [possible values: r, c, g, p, k, j, s, f]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.array = Some(a);
                }
                'u' => {
                    if !seen.insert("func") {
                        return Err(err_with_usage(
                            "the argument '--func <func_length>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "func", "func_length")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.func = Some(n);
                }
                'p' => {
                    if !seen.insert("places") {
                        return Err(err_with_usage(
                            "the argument '--places <func_places>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "places", "func_places")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.places = Some(n);
                }
                'r' => {
                    if !seen.insert("prefix") {
                        return Err(err_with_usage(
                            "the argument '--prefix <prefix>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "prefix", "prefix")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--prefix <prefix>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.prefix = Some(b);
                }
                _ => {
                    return Err(err_with_usage(format!(
                        "unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'",
                        arg, arg, arg
                    )));
                }
            }
            i += 1;
            continue;
        }

        // Positional argument
        if positional_seen {
            return Err(err_with_usage(format!(
                "unexpected argument '{}' found",
                arg
            )));
        }
        args.input_file = Some(arg);
        positional_seen = true;
        i += 1;
    }
    Ok(Ok(args))
}

fn parse_int_kind(_e: &std::num::ParseIntError) -> &'static str {
    "InvalidDigit"
}

enum SpecialAction {
    Help,
    Version,
}

fn read_input(args: &Args) -> io::Result<Vec<u8>> {
    let len_limit = args.len;
    let mut buf = Vec::new();
    if let Some(path) = &args.input_file {
        let mut f = File::open(path)?;
        if let Some(l) = len_limit {
            if l > 0 {
                let mut limited = f.take(l as u64);
                limited.read_to_end(&mut buf)?;
                return Ok(buf);
            }
        }
        f.read_to_end(&mut buf)?;
    } else {
        let stdin = io::stdin();
        let mut lock = stdin.lock();
        if let Some(l) = len_limit {
            if l > 0 {
                let mut limited = (&mut lock).take(l as u64);
                limited.read_to_end(&mut buf)?;
                return Ok(buf);
            }
        }
        lock.read_to_end(&mut buf)?;
    }
    Ok(buf)
}

fn color_for_byte(b: u8) -> u8 {
    if b == 0 {
        22
    } else {
        b
    }
}

fn colorize(color: bool, b: u8, s: &str) -> String {
    if color {
        format!("\x1b[38;5;{}m{}\x1b[0m", color_for_byte(b), s)
    } else {
        s.to_string()
    }
}

fn ascii_of(b: u8) -> char {
    if (0x20..=0x7e).contains(&b) {
        b as char
    } else {
        '.'
    }
}

fn print_dump(data: &[u8], args: &Args, color: bool, out: &mut impl Write) -> io::Result<()> {
    let cols = args.cols.unwrap_or(DEFAULT_COLS);
    let format = args.format.unwrap_or(Format::LowerHex);
    let prefix_on = args.prefix.unwrap_or(true);

    // Cell width (including trailing space) when a cell is filled:
    // Without prefix: digits + 1
    // With prefix: 2 + digits + 1
    // Missing cells are always 5 spaces.

    let digits = match format {
        Format::Octal => 4,
        Format::LowerHex | Format::UpperHex => 2,
        Format::Binary => 8,
    };
    let filled_width = if prefix_on { 2 + digits + 1 } else { digits + 1 };

    let chunk_size = if cols == 0 { 1 } else { cols };
    let total = data.len();
    let mut addr: usize = 0;

    loop {
        let remaining = total.saturating_sub(addr);
        let n = remaining.min(chunk_size);
        let row = &data[addr..addr + n];

        // Print address
        write!(out, "0x{:06x}: ", addr)?;

        // Print hex cells
        let display_cells = cols.max(n);
        for i in 0..display_cells {
            if i < n {
                let b = row[i];
                let mut cell = String::new();
                if prefix_on {
                    cell.push_str(format.prefix());
                }
                cell.push_str(&format.format_byte(b));
                let cell_str = colorize(color, b, &cell);
                write!(out, "{} ", cell_str)?;
            } else {
                // Missing cell: 5 spaces regardless
                write!(out, "     ")?;
            }
        }

        // Print ASCII (no extra separator; last cell's trailing space serves as separator)
        for &b in row {
            let ch = ascii_of(b);
            let ch_s = ch.to_string();
            let colored = colorize(color, b, &ch_s);
            write!(out, "{}", colored)?;
        }

        writeln!(out)?;

        addr += n;
        if n < chunk_size {
            break;
        }
    }

    writeln!(out, "   bytes: {}", total)?;
    Ok(())
}

fn print_wave(n: usize, places: usize, out: &mut impl Write) -> io::Result<()> {
    for i in 0..n {
        let val = if n == 0 {
            0.0
        } else {
            (std::f64::consts::PI / 2.0 * (i as f64) / (n as f64)).sin()
        };
        write!(out, "{:.*},", places, val)?;
        if (i + 1) % 10 == 0 {
            writeln!(out)?;
        }
    }
    writeln!(out)?;
    Ok(())
}

fn print_array(data: &[u8], args: &Args, fmt_kind: ArrayFormat, out: &mut impl Write) -> io::Result<()> {
    let cols_raw = args.cols.unwrap_or(DEFAULT_COLS);
    let cols = if cols_raw == 0 { 1 } else { cols_raw };
    let n = data.len();

    // Header
    let header = match fmt_kind {
        ArrayFormat::Rust => format!("let ARRAY: [u8; {}] = [\n", n),
        ArrayFormat::C => format!("unsigned char ARRAY[{}] = {{\n", n),
        ArrayFormat::Golang => format!("a := [{}]byte{{\n", n),
        ArrayFormat::Python => "a = [\n".to_string(),
        ArrayFormat::Kotlin => "val a = byteArrayOf(\n".to_string(),
        ArrayFormat::Java => "byte[] a = new byte[]{\n".to_string(),
        ArrayFormat::Swift => "let a: [UInt8] = [\n".to_string(),
        ArrayFormat::Fsharp => "let a = [|\n".to_string(),
    };
    out.write_all(header.as_bytes())?;

    // Body
    let (elem_fmt, sep, always_sep): (fn(u8) -> String, &str, bool) = match fmt_kind {
        ArrayFormat::Rust => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::C => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Golang => (|b| format!("0x{:02x}", b), ", ", true),
        ArrayFormat::Python => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Kotlin => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Java => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Swift => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Fsharp => (|b| format!("0x{:02x}uy", b), "; ", false),
    };

    out.write_all(b"    ")?;
    for i in 0..n {
        let s = elem_fmt(data[i]);
        out.write_all(s.as_bytes())?;
        if always_sep || i < n - 1 {
            out.write_all(sep.as_bytes())?;
        }
        if (i + 1) % cols == 0 {
            out.write_all(b"\n    ")?;
        }
    }
    out.write_all(b"\n")?;

    // Footer
    let footer = match fmt_kind {
        ArrayFormat::Rust => "];\n",
        ArrayFormat::C => "};\n",
        ArrayFormat::Golang => "}\n",
        ArrayFormat::Python => "]\n",
        ArrayFormat::Kotlin => ")\n",
        ArrayFormat::Java => "};\n",
        ArrayFormat::Swift => "]\n",
        ArrayFormat::Fsharp => "|]\n",
    };
    out.write_all(footer.as_bytes())?;
    Ok(())
}

fn decide_color(args: &Args) -> bool {
    match args.color {
        Some(v) => v,
        None => {
            if env::var_os("NO_COLOR").is_some() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    }
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = program_name();

    let parsed = match parse_args(&argv) {
        Ok(Ok(a)) => a,
        Ok(Err(SpecialAction::Help)) => {
            print_help(&prog);
            return ExitCode::SUCCESS;
        }
        Ok(Err(SpecialAction::Version)) => {
            print_version();
            return ExitCode::SUCCESS;
        }
        Err(e) => {
            eprintln!("error: {}", e.msg);
            eprintln!();
            if e.show_usage {
                eprintln!("{}", usage_line(&prog));
                eprintln!();
            }
            eprintln!("For more information, try '--help'.");
            return ExitCode::from(2);
        }
    };

    // Wave mode (-u)
    if let Some(n) = parsed.func {
        let places = parsed.places.unwrap_or(DEFAULT_PLACES);
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        if let Err(_e) = print_wave(n, places, &mut lock) {
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    // Read data
    let data = match read_input(&parsed) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: {}", e);
            return ExitCode::from(1);
        }
    };

    let color = decide_color(&parsed);

    let stdout = io::stdout();
    let mut lock = stdout.lock();

    // Array mode (-a)
    if let Some(fmt) = parsed.array {
        if let Err(_e) = print_array(&data, &parsed, fmt, &mut lock) {
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    if let Err(_e) = print_dump(&data, &parsed, color, &mut lock) {
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}
