}

fn parse_args(argv: &[String]) -> Result<Result<Args, SpecialAction>, ParseError> {
    let mut args = Args::default();
    let mut i = 1;
    let mut positional_seen = false;
    let mut after_dd = false;

    // Track which options have been seen (for duplicate detection)
    let mut seen = std::collections::HashSet::new();

    while i < argv.len() {
        let arg = argv[i].clone();

        if after_dd {
