                            v
                        ),
                        show_usage: true,
                    })?;
                    args.format = Some(f);
                }
                't' => {
                    if !seen.insert("color") {
                        return Err(err_with_usage(
                            "the argument '--color <color>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "color", "color")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--color <color>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.color = Some(b);
                }
                'a' => {
                    if !seen.insert("array") {
                        return Err(err_with_usage(
                            "the argument '--array <array_format>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "array", "array_format")?;
                    let a = parse_array(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--array <array_format>'\n  [possible values: r, c, g, p, k, j, s, f]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.array = Some(a);
                }
                'u' => {
                    if !seen.insert("func") {
                        return Err(err_with_usage(
                            "the argument '--func <func_length>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "func", "func_length")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.func = Some(n);
                }
                'p' => {
                    if !seen.insert("places") {
                        return Err(err_with_usage(
                            "the argument '--places <func_places>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "places", "func_places")?;
                    let n = v.parse::<usize>().map_err(|_| ParseError {
                        msg: "invalid digit found in string".to_string(),
                        show_usage: false,
                    })?;
                    args.places = Some(n);
                }
                'r' => {
                    if !seen.insert("prefix") {
                        return Err(err_with_usage(
                            "the argument '--prefix <prefix>' cannot be used multiple times",
                        ));
                    }
                    let v = take_val(&mut i, inline, "prefix", "prefix")?;
                    let b = parse_bool(&v).ok_or_else(|| ParseError {
                        msg: format!(
                            "invalid value '{}' for '--prefix <prefix>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?;
                    args.prefix = Some(b);
                }
                _ => {
                    return Err(err_with_usage(format!(
                        "unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'",
                        arg, arg, arg
                    )));
                }
            }
            i += 1;
            continue;
        }

        // Positional argument
        if positional_seen {
            return Err(err_with_usage(format!(
                "unexpected argument '{}' found",
                arg
            )));
        }
        args.input_file = Some(arg);
        positional_seen = true;
        i += 1;
    }
    Ok(Ok(args))
}

fn parse_int_kind(_e: &std::num::ParseIntError) -> &'static str {
    "InvalidDigit"
}

enum SpecialAction {
    Help,
    Version,
}

fn read_input(args: &Args) -> io::Result<Vec<u8>> {
    let len_limit = args.len;
    let mut buf = Vec::new();
    if let Some(path) = &args.input_file {
        let mut f = File::open(path)?;
        if let Some(l) = len_limit {
            if l > 0 {
                let mut limited = f.take(l as u64);
                limited.read_to_end(&mut buf)?;
                return Ok(buf);
            }
        }
        f.read_to_end(&mut buf)?;
    } else {
        let stdin = io::stdin();
        let mut lock = stdin.lock();
        if let Some(l) = len_limit {
            if l > 0 {
                let mut limited = (&mut lock).take(l as u64);
                limited.read_to_end(&mut buf)?;
                return Ok(buf);
            }
        }
        lock.read_to_end(&mut buf)?;
    }
    Ok(buf)
}

fn color_for_byte(b: u8) -> u8 {
    if b == 0 {
        22
    } else {
        b
    }
}

fn colorize(color: bool, b: u8, s: &str) -> String {
    if color {
        format!("\x1b[38;5;{}m{}\x1b[0m", color_for_byte(b), s)
    } else {
        s.to_string()
    }
}

fn ascii_of(b: u8) -> char {
    if (0x20..=0x7e).contains(&b) {
        b as char
    } else {
        '.'
    }
}

fn print_dump(data: &[u8], args: &Args, color: bool, out: &mut impl Write) -> io::Result<()> {
    let cols = args.cols.unwrap_or(DEFAULT_COLS);
    let format = args.format.unwrap_or(Format::LowerHex);
    let prefix_on = args.prefix.unwrap_or(true);

    // Cell width (including trailing space) when a cell is filled:
    // Without prefix: digits + 1
    // With prefix: 2 + digits + 1
    // Missing cells are always 5 spaces.

    let digits = match format {
        Format::Octal => 4,
        Format::LowerHex | Format::UpperHex => 2,
        Format::Binary => 8,
    };
    let filled_width = if prefix_on { 2 + digits + 1 } else { digits + 1 };

    let chunk_size = if cols == 0 { 1 } else { cols };
    let total = data.len();
    let mut addr: usize = 0;

    loop {
        let remaining = total.saturating_sub(addr);
        let n = remaining.min(chunk_size);
        let row = &data[addr..addr + n];

        // Print address
        write!(out, "0x{:06x}: ", addr)?;

        // Print hex cells
        let display_cells = cols.max(n);
        for i in 0..display_cells {
            if i < n {
                let b = row[i];
                let mut cell = String::new();
                if prefix_on {
                    cell.push_str(format.prefix());
                }
                cell.push_str(&format.format_byte(b));
                let cell_str = colorize(color, b, &cell);
                write!(out, "{} ", cell_str)?;
            } else {
                // Missing cell: 5 spaces regardless
                write!(out, "     ")?;
            }
        }

        // Print ASCII (no extra separator; last cell's trailing space serves as separator)
        for &b in row {
            let ch = ascii_of(b);
            let ch_s = ch.to_string();
            let colored = colorize(color, b, &ch_s);
            write!(out, "{}", colored)?;
        }

        writeln!(out)?;

        addr += n;
        if n < chunk_size {
            break;
        }
    }

    writeln!(out, "   bytes: {}", total)?;
    Ok(())
}

fn print_wave(n: usize, places: usize, out: &mut impl Write) -> io::Result<()> {
    for i in 0..n {
        let val = if n == 0 {
            0.0
        } else {
            (std::f64::consts::PI / 2.0 * (i as f64) / (n as f64)).sin()
        };
        write!(out, "{:.*},", places, val)?;
        if (i + 1) % 10 == 0 {
            writeln!(out)?;
        }
    }
    writeln!(out)?;
    Ok(())
}

fn print_array(data: &[u8], args: &Args, fmt_kind: ArrayFormat, out: &mut impl Write) -> io::Result<()> {
    let cols_raw = args.cols.unwrap_or(DEFAULT_COLS);
    let cols = if cols_raw == 0 { 1 } else { cols_raw };
    let n = data.len();

    // Header
    let header = match fmt_kind {
        ArrayFormat::Rust => format!("let ARRAY: [u8; {}] = [\n", n),
        ArrayFormat::C => format!("unsigned char ARRAY[{}] = {{\n", n),
        ArrayFormat::Golang => format!("a := [{}]byte{{\n", n),
        ArrayFormat::Python => "a = [\n".to_string(),
        ArrayFormat::Kotlin => "val a = byteArrayOf(\n".to_string(),
        ArrayFormat::Java => "byte[] a = new byte[]{\n".to_string(),
        ArrayFormat::Swift => "let a: [UInt8] = [\n".to_string(),
        ArrayFormat::Fsharp => "let a = [|\n".to_string(),
    };
    out.write_all(header.as_bytes())?;

    // Body
    let (elem_fmt, sep, always_sep): (fn(u8) -> String, &str, bool) = match fmt_kind {
        ArrayFormat::Rust => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::C => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Golang => (|b| format!("0x{:02x}", b), ", ", true),
        ArrayFormat::Python => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Kotlin => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Java => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Swift => (|b| format!("0x{:02x}", b), ", ", false),
        ArrayFormat::Fsharp => (|b| format!("0x{:02x}uy", b), "; ", false),
    };

    out.write_all(b"    ")?;
    for i in 0..n {
        let s = elem_fmt(data[i]);
        out.write_all(s.as_bytes())?;
        if always_sep || i < n - 1 {
            out.write_all(sep.as_bytes())?;
        }
        if (i + 1) % cols == 0 {
            out.write_all(b"\n    ")?;
        }
    }
    out.write_all(b"\n")?;

    // Footer
    let footer = match fmt_kind {
        ArrayFormat::Rust => "];\n",
        ArrayFormat::C => "};\n",
        ArrayFormat::Golang => "}\n",
        ArrayFormat::Python => "]\n",
        ArrayFormat::Kotlin => ")\n",
        ArrayFormat::Java => "};\n",
        ArrayFormat::Swift => "]\n",
        ArrayFormat::Fsharp => "|]\n",
    };
    out.write_all(footer.as_bytes())?;
    Ok(())
}

fn decide_color(args: &Args) -> bool {
    match args.color {
        Some(v) => v,
        None => {
            if env::var_os("NO_COLOR").is_some() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    }
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = program_name();

    let parsed = match parse_args(&argv) {
        Ok(Ok(a)) => a,
        Ok(Err(SpecialAction::Help)) => {
            print_help(&prog);
            return ExitCode::SUCCESS;
        }
        Ok(Err(SpecialAction::Version)) => {
            print_version();
            return ExitCode::SUCCESS;
        }
        Err(e) => {
            eprintln!("error: {}", e.msg);
            eprintln!();
            if e.show_usage {
                eprintln!("{}", usage_line(&prog));
                eprintln!();
            }
            eprintln!("For more information, try '--help'.");
            return ExitCode::from(2);
        }
    };

    // Wave mode (-u)
    if let Some(n) = parsed.func {
        let places = parsed.places.unwrap_or(DEFAULT_PLACES);
        let stdout = io::stdout();
        let mut lock = stdout.lock();
        if let Err(_e) = print_wave(n, places, &mut lock) {
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    // Read data
    let data = match read_input(&parsed) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("error: {}", e);
            return ExitCode::from(1);
        }
    };

    let color = decide_color(&parsed);

    let stdout = io::stdout();
    let mut lock = stdout.lock();

    // Array mode (-a)
    if let Some(fmt) = parsed.array {
        if let Err(_e) = print_array(&data, &parsed, fmt, &mut lock) {
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    if let Err(_e) = print_dump(&data, &parsed, color, &mut lock) {
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}
