enum CliError {
    // clap-style (exit 2)
    Clap { msg: String, show_usage: bool },
    // custom parse-int error (exit 1): prints custom message
    IntParse { short: char, long: &'static str },
    // file / IO error (exit 1): plain message
    Io(String),
}

enum SpecialAction {
    Help,
    Version,
}

type ArgKey = &'static str;

fn set_once<T>(
    seen: &mut std::collections::HashSet<ArgKey>,
    key: ArgKey,
    long_name: &str,
    meta: &str,
) -> Result<(), CliError> {
    if !seen.insert(key) {
        return Err(CliError::Clap {
            msg: format!(
                "the argument '--{} <{}>' cannot be used multiple times",
                long_name, meta
            ),
            show_usage: true,
        });
    }
    Ok(())
}

fn parse_usize(
    s: &str,
    _long: &str,
    short: char,
    long_static: &'static str,
) -> Result<usize, CliError> {
    s.parse::<usize>().map_err(|_| CliError::IntParse {
        short,
        long: long_static,
    })
}

fn take_value(
    i: &mut usize,
    provided: Option<String>,
    argv: &[String],
    long_name: &str,
    meta: &str,
) -> Result<String, CliError> {
    if let Some(v) = provided {
        Ok(v)
    } else {
        *i += 1;
        if *i < argv.len() {
            Ok(argv[*i].clone())
        } else {
            Err(CliError::Clap {
                msg: format!(
                    "a value is required for '--{} <{}>' but none was supplied",
                    long_name, meta
                ),
                show_usage: false,
            })
        }
    }
}

fn parse_args(argv: &[String]) -> Result<Result<Args, SpecialAction>, CliError> {
    let mut args = Args::default();
    let mut i = 1;
    let mut positional_seen = false;
    let mut after_dd = false;
    let mut seen: std::collections::HashSet<ArgKey> = std::collections::HashSet::new();

    while i < argv.len() {
        let arg = argv[i].clone();

        if after_dd {
            if positional_seen {
                return Err(CliError::Clap {
                    msg: format!("unexpected argument '{}' found", arg),
                    show_usage: true,
                });
            }
            args.input_file = Some(arg);
            positional_seen = true;
            i += 1;
            continue;
        }

        if arg == "--" {
            after_dd = true;
            i += 1;
            continue;
        }

        if arg == "-h" || arg == "--help" {
            return Ok(Err(SpecialAction::Help));
        }
        if arg == "-V" || arg == "--version" {
            return Ok(Err(SpecialAction::Version));
        }

        if let Some(rest) = arg.strip_prefix("--help=") {
            return Err(CliError::Clap {
                msg: format!(
                    "unexpected value '{}' for '--help' found; no more were expected",
                    rest
                ),
                show_usage: true,
            });
        }

        if let Some(stripped) = arg.strip_prefix("--") {
            let (name_str, value) = if let Some(eq) = stripped.find('=') {
                (stripped[..eq].to_string(), Some(stripped[eq + 1..].to_string()))
            } else {
                (stripped.to_string(), None)
            };
            let name = name_str.as_str();
            match name {
                "cols" => {
                    set_once(&mut seen, "cols", "cols", "columns")?;
                    let v = take_value(&mut i, value, argv, "cols", "columns")?;
                    args.cols = Some(parse_usize(&v, "cols", 'c', "cols")?);
                }
                "len" => {
                    set_once(&mut seen, "len", "len", "len")?;
                    let v = take_value(&mut i, value, argv, "len", "len")?;
                    args.len = Some(parse_usize(&v, "len", 'l', "len")?);
                }
                "format" => {
                    set_once(&mut seen, "format", "format", "format")?;
                    let v = take_value(&mut i, value, argv, "format", "format")?;
                    args.format = Some(parse_format(&v).ok_or_else(|| CliError::Clap {
                        msg: format!(
                            "invalid value '{}' for '--format <format>'\n  [possible values: o, x, X, b]",
                            v
                        ),
                        show_usage: true,
                    })?);
                }
                "color" => {
                    set_once(&mut seen, "color", "color", "color")?;
                    let v = take_value(&mut i, value, argv, "color", "color")?;
                    args.color = Some(parse_bool(&v).ok_or_else(|| CliError::Clap {
                        msg: format!(
                            "invalid value '{}' for '--color <color>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?);
                }
                "array" => {
                    set_once(&mut seen, "array", "array", "array_format")?;
                    let v = take_value(&mut i, value, argv, "array", "array_format")?;
                    args.array = Some(parse_array(&v).ok_or_else(|| CliError::Clap {
                        msg: format!(
                            "invalid value '{}' for '--array <array_format>'\n  [possible values: r, c, g, p, k, j, s, f]",
                            v
                        ),
                        show_usage: true,
                    })?);
                }
                "func" => {
                    set_once(&mut seen, "func", "func", "func_length")?;
                    let v = take_value(&mut i, value, argv, "func", "func_length")?;
                    args.func = Some(parse_usize(&v, "func", 'u', "func")?);
                }
                "places" => {
                    set_once(&mut seen, "places", "places", "func_places")?;
                    let v = take_value(&mut i, value, argv, "places", "func_places")?;
                    args.places = Some(parse_usize(&v, "places", 'p', "places")?);
                }
                "prefix" => {
                    set_once(&mut seen, "prefix", "prefix", "prefix")?;
                    let v = take_value(&mut i, value, argv, "prefix", "prefix")?;
                    args.prefix = Some(parse_bool(&v).ok_or_else(|| CliError::Clap {
                        msg: format!(
                            "invalid value '{}' for '--prefix <prefix>'\n  [possible values: 0, 1]",
                            v
                        ),
                        show_usage: true,
                    })?);
                }
                _ => {
                    return Err(CliError::Clap {
                        msg: format!(
                            "unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'",
                            arg, arg, arg
                        ),
                        show_usage: true,
                    });
                }
            }
            i += 1;
            continue;
        }

        if arg.starts_with('-') && arg.len() >= 2 && arg != "-" {
            let bytes = arg.as_bytes();
            let c = bytes[1] as char;
            let inline = if bytes.len() > 2 {
                Some(String::from_utf8_lossy(&bytes[2..]).into_owned())
            } else {
                None
            };
            match c {
                'c' => {
                    set_once(&mut seen, "cols", "cols", "columns")?;
                    let v = take_value(&mut i, inline, argv, "cols", "columns")?;
                    args.cols = Some(parse_usize(&v, "cols", 'c', "cols")?);
                }
                'l' => {
                    set_once(&mut seen, "len", "len", "len")?;
                    let v = take_value(&mut i, inline, argv, "len", "len")?;
                    args.len = Some(parse_usize(&v, "len", 'l', "len")?);
