enum CliError {
    // clap-style (exit 2)
    Clap { msg: String, show_usage: bool },
    // custom parse-int error (exit 1): prints custom message
    IntParse { short: char, long: &'static str },
    // file / IO error (exit 1): plain message
    Io(String),
}

enum SpecialAction {
    Help,
    Version,
}

type ArgKey = &'static str;

fn set_once<T>(
    seen: &mut std::collections::HashSet<ArgKey>,
    key: ArgKey,
    long_name: &str,
    meta: &str,
) -> Result<(), CliError> {
    if !seen.insert(key) {
        return Err(CliError::Clap {
            msg: format!(
                "the argument '--{} <{}>' cannot be used multiple times",
                long_name, meta
            ),
            show_usage: true,
        });
    }
    Ok(())
}

fn parse_usize(
    s: &str,
    _long: &str,
    short: char,
    long_static: &'static str,
) -> Result<usize, CliError> {
    s.parse::<usize>().map_err(|_| CliError::IntParse {
        short,
        long: long_static,
    })
}

fn take_value(
    i: &mut usize,
    provided: Option<String>,
    argv: &[String],
    long_name: &str,
    meta: &str,
) -> Result<String, CliError> {
    if let Some(v) = provided {
        Ok(v)
    } else {
        *i += 1;
        if *i < argv.len() {
            Ok(argv[*i].clone())
        } else {
            Err(CliError::Clap {
                msg: format!(
                    "a value is required for '--{} <{}>' but none was supplied",
                    long_name, meta
                ),
                show_usage: false,
            })
        }
    }
}

